export class ParseError extends Error {
  constructor(line, message) {
    super(message)
    this.line = line
  }
}

export function parseElection(input) {
  const rawLines = input.split('\n')
  if (rawLines.length > 0 && rawLines[rawLines.length - 1] === '') {
    rawLines.pop()
  }

  let candidates = null
  const candidateSet = new Set()
  const ballots = []
  let ballotsSeen = false

  for (let i = 0; i < rawLines.length; i++) {
    const lineNo = i + 1
    const trimmed = rawLines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'candidates') {
      if (candidates !== null || ballotsSeen) {
        throw new ParseError(lineNo, 'candidates must be declared once, before any ballot')
      }
      const names = words.slice(1)
      if (names.length === 0) {
        throw new ParseError(lineNo, 'expected candidates <name>...')
      }
      for (const name of names) {
        if (!NAME_RE.test(name)) {
          throw new ParseError(lineNo, `invalid candidate name ${name}`)
        }
        if (candidateSet.has(name)) {
          throw new ParseError(lineNo, `candidate ${name} is declared twice`)
        }
        candidateSet.add(name)
      }
      candidates = names
    } else if (directive === 'ballot') {
      if (candidates === null) {
        throw new ParseError(lineNo, 'candidates must be declared once, before any ballot')
      }
      ballotsSeen = true
      if (words.length < 3) {
        throw new ParseError(lineNo, 'expected ballot <count> <candidate>...')
      }
      const countWord = words[1]
      if (!COUNT_RE.test(countWord)) {
        throw new ParseError(lineNo, 'count must be a positive integer')
      }
      const count = Number(countWord)
      const ranking = words.slice(2)
      const seen = new Set()
      for (const name of ranking) {
        if (!candidateSet.has(name)) {
          throw new ParseError(lineNo, `unknown candidate ${name}`)
        }
        if (seen.has(name)) {
          throw new ParseError(lineNo, `candidate ${name} is repeated`)
        }
        seen.add(name)
      }
      ballots.push({ count, ranking })
    } else {
      throw new ParseError(lineNo, `unknown directive ${directive}`)
    }
  }

  if (candidates === null) {
    throw new ParseError(null, 'no candidates')
  }

  return { candidates, ballots }
}
"}

