 * Runs the instant-runoff count over parsed candidates and ballots.
 */

function chooseElimination(tiedNames, history) {
  let candidatesSet = tiedNames.slice()

  outer: while (true) {
    for (let r = 0; r < history.length; r++) {
      const counts = candidatesSet.map((n) => history[r].get(n))
      const allEqual = counts.every((c) => c === counts[0])
      if (!allEqual) {
        const min = Math.min(...counts)
        candidatesSet = candidatesSet.filter((n) => history[r].get(n) === min)
        continue outer
      }
    }
    break
  }

  if (candidatesSet.length === 1) return candidatesSet[0]
  return candidatesSet.slice().sort().pop()
}

export function runElection(candidates, ballots) {
  let continuing = new Set(candidates)
  const history = []
  const rounds = []
  let winner = null

  while (true) {
    const counts = new Map()
    for (const c of continuing) counts.set(c, 0)
    let exhausted = 0

    for (const ballot of ballots) {
      const choice = ballot.ranking.find((name) => continuing.has(name))
      if (choice === undefined) {
        exhausted += ballot.count
      } else {
        counts.set(choice, counts.get(choice) + ballot.count)
      }
    }

    history.push(counts)

    const activeTotal = [...counts.values()].reduce((a, b) => a + b, 0)

    const entries = [...counts.entries()]
      .map(([name, votes]) => ({ name, votes }))
      .sort((a, b) => (b.votes - a.votes) || (a.name < b.name ? -1 : a.name > b.name ? 1 : 0))

    if (activeTotal === 0) {
      rounds.push({ entries, exhausted, eliminated: null })
      winner = null
      break
    }

    const majorityWinner = entries.find((e) => e.votes * 2 > activeTotal)
    if (majorityWinner) {
      rounds.push({ entries, exhausted, eliminated: null })
      winner = majorityWinner.name
      break
    }

    const minVotes = Math.min(...entries.map((e) => e.votes))
    const tied = entries.filter((e) => e.votes === minVotes).map((e) => e.name)
    const eliminated = tied.length === 1 ? tied[0] : chooseElimination(tied, history)

    rounds.push({ entries, exhausted, eliminated })
    continuing.delete(eliminated)
  }

  return { rounds, winner }
}
"}

