/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import fs from 'node:fs'
import { parseElection, ParseError } from './parse.js'
import { runElection } from './election.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'rounds' && args[0] !== 'tally')) {
    fail('usage: cli.js rounds|tally')
    return
  }
  const mode = args[0]

  const input = fs.readFileSync(0, 'utf8')

  let election
  try {
    election = parseElection(input)
  } catch (e) {
    if (e instanceof ParseError) {
      if (e.line === null) {
        fail(e.message)
      } else {
        fail(`line ${e.line}: ${e.message}`)
      }
      return
    }
    throw e
  }

  const { rounds, winner } = runElection(election.candidates, election.ballots)

  const lines = []
  if (mode === 'rounds') {
    rounds.forEach((round, idx) => {
      const parts = round.entries.map((e) => `${e.name}=${e.votes}`)
      parts.push(`exhausted=${round.exhausted}`)
      lines.push(`round ${idx + 1}: ${parts.join(' ')}`)
      if (round.eliminated !== null) {
        lines.push(`eliminated ${round.eliminated}`)
      }
    })
  } else {
    lines.push(`rounds ${rounds.length}`)
  }

  lines.push(winner === null ? 'no winner' : `winner ${winner}`)

  process.stdout.write(lines.join('\n') + '\n')
}

main()
"}

